function validate([head]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 100000) return 'The list holds 1 to 10^5 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < -5000 || v > 5000)) return 'Each value is an integer from -5000 to 5000.';
  for (let i = 1; i < head.length; i++) {
    if (Math.abs(head[i]) < Math.abs(head[i - 1])) return 'Absolute values must never decrease along the list.';
  }
  return null;
}

