function sortLinkedList(head) {
  const values = [];
  for (let p = head; p; p = p.next) values.push(p.val);
  values.sort((a, b) => a - b);
  let result = null;
  for (let k = values.length - 1; k >= 0; k--) result = new ListNode(values[k], result);
  return result;
}

