function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(1, 8);
  const top = size === 'large' ? [5000, 50][int(0, 1)] : (rand() < 0.7 ? 6 : 5000);
  const mode = int(0, 3); // 0 mixed, 1 all negative, 2 all non-negative, 3 mostly negative
  const sizes = Array.from({ length: n }, () => int(0, top)).sort((a, b) => a - b);
  const list = sizes.map(a => {
    const negative = mode === 1 ? true : mode === 2 ? false : mode === 3 ? rand() < 0.8 : rand() < 0.5;
    return negative && a !== 0 ? -a : a;
  });
  return [list];
}
